def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find the full-width or full-height separator line.
    separator = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            separator = ("h", r, grid[r][0])
            break
    if separator is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1 and vals[0] != bg:
                separator = ("v", c, vals[0])
                break

    if separator is None:
        return [row[:] for row in grid]

    orient, line, line_color = separator
    obj_colors = [v for v in counts if v not in (bg, line_color)]
    if not obj_colors:
        return [row[:] for row in grid]
    obj = max(obj_colors, key=lambda v: counts[v])

    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    out = [row[:] for row in grid]

    if orient == "h":
        lo, hi = min(r for r, c in cells), max(r for r, c in cells)
        dr = line + 1 - lo if lo > line else line - 1 - hi
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r + dr][c] = obj
        trailing = max(r for r, c in cells) + dr + 1 if dr < 0 else min(r for r, c in cells) + dr - 1
        for c in range(w):
            out[trailing][c] = 8
    else:
        lo, hi = min(c for r, c in cells), max(c for r, c in cells)
        dc = line + 1 - lo if lo > line else line - 1 - hi
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r][c + dc] = obj
        trailing = max(c for r, c in cells) + dc + 1 if dc < 0 else min(c for r, c in cells) + dc - 1
        for r in range(h):
            out[r][trailing] = 8

    return out
